func modelIcon(role string) string {
	switch role {
	case "embedding":
		return "database"
	case "jev":
		return "spark"
	default:
		return "models"
	}
}

func modelURLLabel(role string) string {
	if role == "jev" {
		return "System One Endpoint URL"
	}
	return "API Base URL"
}

func modelURLPlaceholder(role string) string {
	switch role {
	case "embedding":
		return "http://127.0.0.1:11434/v1"
	case "jev":
		return "https://openrouter.ai/api/v1/systemone"
	default:
		return "https://openrouter.ai/api/v1"
	}
}

func modelPlaceholder(role string) string {
	switch role {
	case "embedding":
		return "nomic-embed-text"
	case "jev":
		return "typesafe/jev-1.14"
	default:
		return "openai/gpt-4o-mini"
	}
}

func keyPlaceholder(hasKey bool) string {
	if hasKey {
		return "地址相同时可留空"
	}
	return "输入 API Key"
}

